function configureVideo({ videoUrl, instruction }) {
  if (
    typeof videoUrl !== "string" ||
    !/^https:\/\/[a-z0-9.-]+(?::443)?\/(?!\/)[^#\s\\]+$/i.test(videoUrl) ||
    /^https:\/\/[^/]+\.invalid\//i.test(videoUrl)
  ) {
    throw new Error("Set a direct HTTPS video URL");
  }
  if (typeof instruction !== "string" || !instruction.trim() || instruction.length > 4000) {
    throw new Error("Enter video analysis instructions of up to 4,000 characters");
  }
  return { videoUrl, instruction };
}
const videoUrl = "https://media.example.invalid/video.mp4";
const instruction =
  "Describe in detail what is visually happening in the video, including key elements, actions, colors, and branding. Note the style, tone, and any notable creative techniques being used.";
return [{ json: configureVideo({ videoUrl, instruction }) }];

function videoMetadata({ size, mime, status }) {
  if (status !== 200 || !Number.isSafeInteger(size) || size < 1 || size > 10 * 1024 * 1024) {
    throw new Error("The video download must contain a complete file of up to 10 MiB");
  }
  const supported = [
    "video/mp4",
    "video/mpeg",
    "video/quicktime",
    "video/mov",
    "video/avi",
    "video/x-flv",
    "video/mpg",
    "video/webm",
    "video/wmv",
    "video/3gpp",
  ];
  if (!supported.includes(mime))
    throw new Error("The download did not return a supported video Content-Type");
  return { length: String(size), mime };
}
const item = $input.first();
const bytes = await helpers.getBinaryDataBuffer(0, "data");
const json = videoMetadata({
  size: bytes.length,
  mime: item.binary.data.mimeType,
  status: item.json.statusCode,
});
return [{ json }];

function uploadSession(headers) {
  const url = Object.entries(headers ?? {}).find(
    ([key]) => key.toLowerCase() === "x-goog-upload-url",
  )?.[1];
  if (
    typeof url !== "string" ||
    !/^https:\/\/generativelanguage\.googleapis\.com\/upload\/v1beta\/files\?[^#\s\\]+$/.test(url)
  ) {
    throw new Error("Gemini did not return a trusted resumable upload URL");
  }
  return url;
}
return [
  {
    json: { url: uploadSession($input.first().json.headers) },
    binary: $("Download the video").first().binary,
  },
];

function uploadedFile({ body, mime, length }) {
  const file = body?.file;
  if (
    !/^files\/[a-z0-9](?:[a-z0-9-]{0,38}[a-z0-9])?$/.test(file?.name ?? "") ||
    file.mimeType !== mime ||
    String(file.sizeBytes) !== length
  ) {
    throw new Error("Gemini upload did not return the matching file metadata");
  }
  const url = "https://generativelanguage.googleapis.com/v1beta/" + file.name;
  if (file.uri !== url) throw new Error("Gemini upload returned an unexpected file URI");
  if (file.state !== "ACTIVE" && file.state !== "PROCESSING") {
    throw new Error("Gemini upload failed to process the video");
  }
  return { fileName: file.name, fileUrl: url, mime };
}
const { mime, length } = $("Check video size and type").first().json;
return [{ json: uploadedFile({ body: $input.first().json, mime, length }) }];

function fileStatus({ file, fileName, fileUrl, mime, instruction, attempt }) {
  if (file?.name !== fileName || file?.uri !== fileUrl || file?.mimeType !== mime) {
    throw new Error("Gemini status did not match the uploaded video");
  }
  if (file.state === "ACTIVE") {
    return {
      processing: false,
      attempt,
      request: {
        contents: [
          {
            role: "user",
            parts: [{ fileData: { fileUri: fileUrl, mimeType: mime } }, { text: instruction }],
          },
        ],
        generationConfig: { maxOutputTokens: 8192, thinkingConfig: { thinkingLevel: "LOW" } },
      },
    };
  }
  if (file.state !== "PROCESSING") throw new Error("Gemini failed to process the uploaded video");
  if (attempt >= 12)
    throw new Error("Gemini video processing did not finish after 12 status checks");
  return { processing: true, attempt, request: null };
}
const { fileName, fileUrl, mime } = $("Check the uploaded Gemini file").first().json;
const { instruction } = $("Set the video URL and instructions").first().json;
return [
  {
    json: fileStatus({
      file: $input.first().json,
      fileName,
      fileUrl,
      mime,
      instruction,
      attempt: $runIndex + 1,
    }),
  },
];

function videoDescription(body) {
  const candidate = body?.candidates?.[0];
  if (candidate?.finishReason !== "STOP") throw new Error("Gemini did not complete video analysis");
  const description = (candidate.content?.parts ?? [])
    .filter((part) => !part.thought && typeof part.text === "string")
    .map((part) => part.text)
    .join("\n")
    .trim();
  if (!description) throw new Error("Gemini returned no video description");
  return { videoDescription: description };
}
return [{ json: videoDescription($input.first().json) }];
